-- Tenant config moves out of hosts/<id>/config.js and into the database, so
-- onboarding a host stops requiring a code change and a deploy.
--
-- Stored as one JSON document rather than columns: the config is deeply
-- nested (villas, pricing, guest message templates, flexibility tiers) and is
-- always read whole. Flat scalars that other queries filter on stay in
-- platform_tenants.
CREATE TABLE IF NOT EXISTS platform_tenant_config (
  tenant_id   TEXT PRIMARY KEY,
  config_json TEXT NOT NULL,
  updated_at  TEXT DEFAULT (datetime('now'))
);

INSERT INTO platform_tenant_config (tenant_id, config_json)
  VALUES ('dwarka', '{"brandName":"Guruvayur Estates","brandShort":"GE Portal","tagline":"Property Management Portal","landingUrl":"https://www.luxuryvillasofguruvayur.com","driveRootId":"1Qyy37HJVo4RQ5MPVmSJt26-SkE65sFva","ownerEmail":"bijisukumar@gmail.com","ownerWhatsApp":"+1 972.876.5101","email":{"guestFrom":"Guruvayur Estates <stay@luxuryvillasofguruvayur.com>","alertFrom":"bgIndia Security <alerts@luxuryvillasofguruvayur.com>","guestBcc":"kerala.luxuryvillas@gmail.com"},"spreadsheetId":"1xpLBxd2Fhx26aNQZ3Z5L4gDB6yJVFsGHf3B1jUDkvQQ","guestFormSheetId":"1Lt1aORPlrisE_4-DobQCecvlyH0yOsD2SAIgJLgyEo0","villas":[{"id":"dwarka","name":"Dwarka","full":"Dwarka — GVR Villa","arrivalFullName":"Dvaraka - Luxury Villas of Guruvayur","location":"Guruvayur","address":"Edappully Gandhinagar Rd, Palayoor, Guruvayur, Kerala 680506, India","mapsLink":"https://maps.app.goo.gl/fjfe4eS4BJmaHh62A","bedrooms":4,"active":true,"logoUrl":"/icons/DwarkaLVGLogo.png","managerName":"RamananKutty","managerUpi":"85471419raman@okicici","managerPhone":"+91 85471 41401","checkinTime":"4:00 PM","checkoutTime":"11:00 AM"}],"turnaround":{"defaultCheckinTime":"16:00","defaultCheckoutTime":"11:00","turnaroundHours":4},"checkinBaseUrl":"https://dwarka.stayvibe360.com","checkinLinkTokens":{"airbnb":"gvr-airbnb","booking_com":"gvr-booking","booking":"gvr-booking","makemytrip":"gvr-mmt","goibibo":"gvr-goibibo","agoda":"gvr-agoda","expedia":"gvr-expedia","vrbo":"gvr-vrbo","direct":"gvr-direct","website":"gvr-direct","whatsapp":"gvr-direct"},"checkinLinkDefaultToken":"gvr-direct","flexibility":{"hero":{"eyebrow":"DIRECT GUESTS · DWARKA VILLA","title":"We go further for families than the clock allows.","intro":"Check-in after 4:00 PM and check-out by 11:00 AM is the standard, here and everywhere. But a family travelling together rarely fits a booking window — so where we can, we stretch it. Here is what those hours are actually for, and how far we are able to go for yours."},"why":{"heading":"Why our timings are what they are","body":["Check-out is by 11:00 AM. Check-in is after 4:00 PM. That gap is five hours, and it is fully used.","Dwarka is a 3,000 sq ft home with four bedrooms and four and a half bathrooms. Between one family leaving and the next arriving, our team works through all of it."],"checklist":["Every bed stripped and remade with fresh linen — nothing is reused between families, ever","Every bathroom deep-cleaned and sanitised","The kitchen cleaned down and restocked, ready for your family to cook in from the moment you arrive","Every bedroom, the living areas, the dining hall and the grounds gone over"],"closing":["We don''t cut corners to turn the house around faster. A home this size simply takes that long to bring back to the standard you would expect when your family walks in.","So when we hold to those hours, it isn''t policy for the sake of policy — it''s the reason the house feels the way it does when you arrive. Your family''s gathering here should be memorable, and this is a large part of how we make sure it is."]},"options":{"heading":"Need to arrive earlier, or leave later? Just ask.","body":["We understand that at times a family needs more flexibility than our normal timings allow — a long drive, small children, elderly parents, a wedding to be at. So rather than turn the request down, tell us which of these two it is, and we will work to it."],"tiers":[{"label":"Must have","lead":"Held for you, guaranteed, at a fraction of a night.","body":"If your family cannot manage without the earlier arrival or later departure, we hold the adjoining night so it is certain. Once we do, that night can''t be offered to anyone else — but we don''t charge for a full extra night. We ask for a fraction of it, 25% or 50% depending on how much extra time you need. We''ll confirm the exact amount once we''ve looked at your dates, and it''s settled before you travel."},{"label":"Or simply ask on the day","lead":"No charge, but no promises either.","body":"If it would be a bonus rather than a necessity, don''t pay for it. Ask us when you arrive: if nobody stayed the night before, or the previous family left early, the extra time is yours at no additional cost. Just please don''t build your travel around it — on a busy week there may be nothing to give."}],"availabilityNote":"One honest note: when the villa is booked back-to-back, there may simply be no gap to give — and we won''t always be able to say yes. If that happens we''ll tell you early rather than leave you hoping, and we''ll look at every option we have to rearrange things around your family before we do.","directNote":"This is something we''re able to offer only to guests who book with us directly. Booking direct means the calendar is ours to hold, so we can set a night aside for your family and price it as a courtesy rather than a full night''s stay. It''s one of the ways we try to keep your costs down.","advanceNote":"Please ask ahead of time. Timing changes need to be agreed and settled before you arrive so we can plan the turnaround around your family — our on-site team is not able to approve changes on the day."},"ota":{"heading":"Booked through a partner?","body":["Any extra night for your current stay has to go through whoever you booked with — those dates sit in their system, and they''ll charge you a full night for it.","You can still deal with us directly from here. When the booking is ours to hold, so is the calendar — and that changes what we are able to do for your family:"],"directPitch":["No platform commission on the booking — that saving stays with you","Flexible arrival and departure at a fraction of a night, never the full rate","Talk straight to the family who owns the home — no call centre, no ticket number","Tell us what your family needs and get an answer from someone who can actually say yes"],"directOptInLabel":"I''d like to book with you directly, to secure the Must have option above.","ctaLabel":"Send me your direct rates","thanks":"Thank you — we''ll come straight back to you with our direct rates."},"form":{"heading":"Tell us what you need (for an existing booking)","needTypes":["Earlier check-in on arrival day","Later check-out on departure day","Both"],"checkinTimeLabel":"What time do you need to arrive?","checkoutTimeLabel":"What time do you need to leave?","priorityLabel":"Type of request","priorities":[{"id":"must_have","label":"Must have — I want it secured, and will pay for it"},{"id":"check_on_arrival","label":"I''ll check back on the day of arrival — no additional payment needed"}],"submitLabel":"Send request — we''ll follow up to confirm","thanks":"Thank you — we''ve got your request. We''ll check the dates and come back to you with what we can do, before you travel."},"tiers":[{"hours":4,"pct":25},{"hours":8,"pct":50}],"channels":["OTA — online partner (Airbnb, Booking.com, MMT…)","Direct with us","Travel agent"],"directChannel":"Direct with us"},"guestMessages":{"hostIntro":{"template":"Namaskaram {firstName}! 🙏\n\nThis is Biji from Guruvayur Villa (Dwarka). I wanted to personally welcome you ahead of your stay on {checkinDateShort}.\n\nAt Guruvayur Villa, we open our home to your family and strive to create a comfortable, memorable experience. To help us prepare for your visit, I''d love to connect briefly to review your reservation, arrival timing, and any special requirements you may have.\n\n*YOUR BOOKING*\n• Check-in: {checkinDateFull} — after {checkinTime}\n• Check-out: {checkoutDateFull} — by {checkoutTime}\n• Guests: {guestCount}\n• Nights: {nights}\n{checkinPrompt}\nPlease let me know a convenient time to connect. We''re looking forward to hosting you and your family.\n\nSnehapoorvam (സ്നേഹപൂർവ്വം),\nBiji | Guruvayur Villa (Dwarka)","checkinPrompt":"\n📝 If you haven''t completed your online check-in registration yet, please do so at your earliest convenience — it''s a mandatory government requirement, and it helps us have everything ready before you arrive:\n{checkinUrl}\n"},"comfortCheck":{"template":"Namaskaram {guestName}! 🙏\n\nWe hope your travel to Guruvayur was comfortable, and that check-in went smoothly with our staff able to assist you well.\n\nWishing you a wonderful stay at {villaName}! If you need anything at all during your time here, {managerName} is just a phone call away — {managerPhone}.\n\nEnjoy your stay! 🏡"},"checkoutDay":{"subject":"Checkout day today — {villaName}","template":"Namaskaram {guestName},\n\nToday is your check-out day at {villaName}. Standard check-out time is {checkoutTime} — please let {managerName} know if you need any assistance before you leave ({managerPhone}).\n\nYou''ll find all your check-out details in the folder left at the villa — please do review it at your convenience.\n\nWe hope you had a truly beautiful and enjoyable time in Guruvayur, with wonderful family moments at {villaName}. Safe travels, and we do hope to welcome you back again soon!\n\nWarm regards,\n{brandName}"},"farewell":{"template":"Namaskaram {guestName}! 🙏\n\nAs your time with us at {villaName} comes to a close, I wanted to personally thank you for staying with us.\n\nIt would mean a lot to know — how was your stay? We do hope our team was able to look after you and your family well, and that {villaName} gave you some truly memorable moments.\n\nWishing you a very safe journey ahead, whether you''re headed home or on to your next destination. It would be our honour to welcome you back again soon.\n\nSnehapoorvam (സ്നേഹപൂർവ്വം),\n{managerName} | Guruvayur Villa (Dwarka)"}},"rentalProperties":[{"id":"rental_1","name":"Tritvam","location":"Kochi, KL","tenantName":"","leaseEnd":"","unitNo":"T4 9D","floor":"9th","building":"Tata Tritvam at Marine Drive","city":"Kochi","hasParking":true,"electricityConsumerNo":"1155466025977","furnishing":"semi furnished"},{"id":"rental_2","name":"Pacifica","location":"OMR, TN","tenantName":"","leaseEnd":"","unitNo":"","floor":"","building":"Pacifica","city":"Chennai","hasParking":false,"electricityConsumerNo":"","furnishing":"non-furnished"},{"id":"rental_3","name":"Pinnacle","location":"TCR, KL","tenantName":"","leaseEnd":"","unitNo":"103","floor":"1st","building":"Pinnacle Residency","city":"Trichur","hasParking":false,"electricityConsumerNo":"","furnishing":"non-furnished"}],"leaseIndia":{"lessorName":"Biji Sukumar","lessorAddress":"Thandayamgattil House, P O Chavakkad, Trichur Dist, Kerala 680501","lessorPan":"AXRPS9969C","executionCity":"Cochin","bank":{"accountName":"Biji Sukumar","bankName":"Federal Bank","accountNumber":"14320100138300","ifsc":"FDRL0001432","swift":"FDRLINBBIBD"},"renewalIncreasePct":5,"maintenanceIncludedInRent":false,"lateFeeTiers":[{"label":"Due on 1st of every month","from":1,"to":1,"fee":0},{"label":"Emergency Grace period (2nd-5th)","from":2,"to":5,"fee":0},{"label":"6th-8th of the month","from":6,"to":8,"fee":2000},{"label":"9th-15th of the month","from":9,"to":15,"fee":7000},{"label":"16th-31st of the month","from":16,"to":31,"fee":12000}],"prematureTermination":{"beforeFullTerm":"LESSEE is to pay broker commission","before6Months":"LESSEE is to pay 1 month additional Rent amount"},"defectNoticeDays":10,"jurisdiction":"Ernakulam"},"estates":[{"id":"pollachi","name":"Pollachi Estate","type":"coconut","manager":"Pradosh","active":true,"incomeCategories":["Mango Harvest Income","Lease income","Govt subsidy","Other income"],"expenseCategories":["Labour wages","Salary","Fertilizer","Pesticide","Tractor / Land tiling","JCB work","Fencing","Irrigation","Water pump","Electricity bill","Land tax","Transport","Housing expenses","Soil evaluation & testing","Tree / plant purchase","Maintenance & repairs","Other expense"]},{"id":"pavutumuri","name":"Pavutumuri Estate","type":"rubber","manager":"RamananKutty","active":true,"tappingRate":2.75,"sheetWeightKg":0.6,"sheetRatePerKg":200,"ottupalRatePerKg":150,"incomeCategories":["Rubber Sheet","Ottupal","Coconut","Lease income","Govt subsidy","Other income"],"expenseCategories":["Rubber Plantation","Coconut Plantation","Overall Farm (gates/fencing/road)","Rubber Labour","Formic Acid","Fertilizer","Tree waterproofing","Smoke house repair","Coconut Labour","House maintenance","Transport","Land tax","Other expense"]}],"breakfastRate":275,"additionalGuestRate":750,"dehuskDefaultRate":1.5,"pricing":{"overflowPerGuestPerNight":750,"overflowMaxRecommended":4,"rateCardMaxGuests":12,"fallbackRateCards":{"dwarka":[{"guests":1,"tariff":4896},{"guests":2,"tariff":4896},{"guests":3,"tariff":6037},{"guests":4,"tariff":7178},{"guests":5,"tariff":8319},{"guests":6,"tariff":9460},{"guests":7,"tariff":10601},{"guests":8,"tariff":11743},{"guests":9,"tariff":12884},{"guests":10,"tariff":14025},{"guests":11,"tariff":15166},{"guests":12,"tariff":16307}]},"discountCategories":[{"id":"loyal_patron","label":"Loyal Patron / Valued Return Guest / Preferred Guest","defaultPct":10},{"id":"elite_guest","label":"Elite Guest","defaultPct":15},{"id":"platinum_guest","label":"Platinum Guest","defaultPct":20},{"id":"b2b_india","label":"B2B – India","defaultPct":10},{"id":"b2b_intl","label":"B2B – International","defaultPct":20},{"id":"custom_amount","label":"Custom Amount","defaultPct":0}],"extraItems":[{"label":"Early Check-in","amount":500},{"label":"Late Check-out","amount":500},{"label":"Early Check-in + Late Check-out","amount":1000},{"label":"Additional Day","amount":0},{"label":"Breakfast","amount":0},{"label":"Floor Bed","amount":750},{"label":"Additional Guest","amount":0},{"label":"Taxi Pick-up","amount":0},{"label":"Drop-off & Pick-up","amount":0},{"label":"Cleaning Fee","amount":1000},{"label":"Event & Culinary Services","amount":0},{"label":"Other","amount":0}]},"theme":{"gold":"#C8903A","goldLight":"#F0D080","dark":"#1A1A1A","darkCard":"#242B3D","darkNav":"#1E2535","text":"#EDF2F7","textMuted":"#8A9BAE","textDim":"#5C7080","green":"#34A853","red":"#c62828","blue":"#185FA5","teal":"#0F6E56"}}')
  ON CONFLICT(tenant_id) DO UPDATE SET config_json = excluded.config_json,
    updated_at = datetime('now');
