 your time here, {managerName} is just a phone call away — {managerPhone}.\n\nEnjoy your stay! 🏡"},"checkoutDay":{"subject":"Checkout day today — {villaName}","template":"Namaskaram {guestName},\n\nToday is your check-out day at {villaName}. Standard check-out time is {checkoutTime} — please let {managerName} know if you need any assistance before you leave ({managerPhone}).\n\nYou''ll find all your check-out details in the folder left at the villa — please do review it at your convenience.\n\nWe hope you had a truly beautiful and enjoyable stay, with wonderful family moments at {villaName}. Safe travels, and we do hope to welcome you back again soon!\n\nWarm regards,\n{brandName}"},"farewell":{"template":"Namaskaram {guestName}! 🙏\n\nAs your time with us at {villaName} comes to a close, I wanted to personally thank you for staying with us.\n\nIt would mean a lot to know — how was your stay? We do hope our team was able to look after you and your family well, and that {villaName} gave you some truly memorable moments.\n\nWishing you a very safe journey ahead, whether you''re headed home or on to your next destination. It would be our honour to welcome you back again soon.\n\nWarm regards,\n{managerName} | Demo Villa"}},"rentalProperties":[],"leaseIndia":{"lessorName":"Demo Lessor","lessorAddress":"Demo Address, Test City, Kerala 680000","lessorPan":"DEMO0000X","executionCity":"Test City","bank":{"accountName":"Demo Lessor","bankName":"Demo Bank","accountNumber":"00000000000000","ifsc":"DEMO0000000","swift":"DEMOINBBXXX"},"renewalIncreasePct":5,"maintenanceIncludedInRent":false,"lateFeeTiers":[{"label":"Due on 1st of every month","from":1,"to":1,"fee":0},{"label":"Emergency Grace period (2nd-5th)","from":2,"to":5,"fee":0},{"label":"6th-8th of the month","from":6,"to":8,"fee":2000},{"label":"9th-15th of the month","from":9,"to":15,"fee":7000},{"label":"16th-31st of the month","from":16,"to":31,"fee":12000}],"prematureTermination":{"beforeFullTerm":"LESSEE is to pay broker commission","before6Months":"LESSEE is to pay 1 month additional Rent amount"},"defectNoticeDays":10,"jurisdiction":"Test City"},"estates":[],"breakfastRate":300,"additionalGuestRate":800,"dehuskDefaultRate":2,"pricing":{"overflowPerGuestPerNight":800,"overflowMaxRecommended":3,"rateCardMaxGuests":10,"fallbackRateCards":{"demovilla":[{"guests":1,"tariff":3000},{"guests":2,"tariff":3000},{"guests":3,"tariff":4000},{"guests":4,"tariff":5000},{"guests":5,"tariff":6000},{"guests":6,"tariff":7000},{"guests":7,"tariff":8000},{"guests":8,"tariff":9000},{"guests":9,"tariff":10000},{"guests":10,"tariff":11000}]},"discountCategories":[{"id":"loyal_patron","label":"Loyal Patron","defaultPct":10},{"id":"b2b_india","label":"B2B – India","defaultPct":10},{"id":"custom_amount","label":"Custom Amount","defaultPct":0}],"extraItems":[{"label":"Early Check-in","amount":500},{"label":"Late Check-out","amount":500},{"label":"Additional Day","amount":0},{"label":"Breakfast","amount":0},{"label":"Other","amount":0}]},"theme":{"gold":"#3A7CC8","goldLight":"#80B0F0","dark":"#1A1A1A","darkCard":"#242B3D","darkNav":"#1E2535","text":"#EDF2F7","textMuted":"#8A9BAE","textDim":"#5C7080","green":"#34A853","red":"#c62828","blue":"#185FA5","teal":"#0F6E56"}}')
